                    auto* menu = qobject_cast<QMenu*>(
                        QApplication::activePopupWidget());
                    auto* groupMenu = menu
                        ? menu->findChild<QMenu*>(
                              QStringLiteral("LaneGroupMenu"))
                        : nullptr;
                    auto* unavailable = groupMenu
                        ? groupMenu->findChild<QAction*>(
                              QStringLiteral("NoLaneGroupsAction"))
                        : nullptr;
                    auto* create = groupMenu
                        ? groupMenu->findChild<QAction*>(
                              QStringLiteral("CreateGroupWithLaneAction"))
                        : nullptr;
                    if (!menu
                        || menu->objectName()
                            != QStringLiteral("LaneHeaderContextMenu")
                        || !groupMenu
                        || !unavailable
                        || unavailable->isEnabled()
                        || !create
                        || !create->isEnabled()) {
                        if (menu) menu->close();
                        return;
                    }

